#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1024
#define MAX_OUT   4096

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *in = argv[2];
    size_t in_len = strlen(in);
    if (in_len > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }
    char out[MAX_OUT];
    size_t out_idx = 0;
    if (strcmp(mode, "escape") == 0) {
        for (size_t i = 0; i < in_len; ++i) {
            unsigned char c = (unsigned char)in[i];
            switch (c) {
                case '\\':
                    if (out_idx + 2 >= MAX_OUT) { puts("INVALID"); return 0; }
                    out[out_idx++] = '\\';
                    out[out_idx++] = '\\';
                    break;
                case '"':
                    if (out_idx + 2 >= MAX_OUT) { puts("INVALID"); return 0; }
                    out[out_idx++] = '\\';
                    out[out_idx++] = '"';
                    break;
                case '\n':
                    if (out_idx + 2 >= MAX_OUT) { puts("INVALID"); return 0; }
                    out[out_idx++] = '\\';
                    out[out_idx++] = 'n';
                    break;
                case '\t':
                    if (out_idx + 2 >= MAX_OUT) { puts("INVALID"); return 0; }
                    out[out_idx++] = '\\';
                    out[out_idx++] = 't';
                    break;
                default:
                    if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                    out[out_idx++] = c;
                    break;
            }
        }
        out[out_idx] = '\0';
        puts(out);
        return 0;
    } else if (strcmp(mode, "unescape") == 0) {
        for (size_t i = 0; i < in_len; ) {
            if (in[i] == '\\') {
                if (i + 1 >= in_len) { puts("INVALID"); return 0; }
                char nxt = in[i + 1];
                switch (nxt) {
                    case '\\':
                        if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                        out[out_idx++] = '\\';
                        i += 2;
                        break;
                    case '"':
                        if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                        out[out_idx++] = '"';
                        i += 2;
                        break;
                    case 'n':
                        if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                        out[out_idx++] = '\n';
                        i += 2;
                        break;
                    case 't':
                        if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                        out[out_idx++] = '\t';
                        i += 2;
                        break;
                    default:
                        puts("INVALID");
                        return 0;
                }
            } else {
                if (out_idx + 1 >= MAX_OUT) { puts("INVALID"); return 0; }
                out[out_idx++] = in[i++];
            }
        }
        out[out_idx] = '\0';
        puts(out);
        return 0;
    } else {
        puts("INVALID_MODE");
        return 0;
    }
}
